module tb_fifo;
    logic clk = 0;
    logic rst_n = 0;
    logic wr_en = 0;
    logic rd_en = 0;
    logic [7:0] data_in = 0;
    logic [7:0] data_out;
    logic full, empty;

    fifo #(.DEPTH(4), .WIDTH(8)) dut (.*);

    always #5 clk = ~clk;

    initial begin
        $display("Testing FIFO with Assertions...");
        rst_n = 0;
        repeat(2) @(posedge clk);
        rst_n = 1;

        // Write data
        for (int i = 0; i < 4; i++) begin
            wr_en = 1;
            data_in = i + 1;
            @(posedge clk);
        end
        wr_en = 0;

        // Read data
        for (int i = 0; i < 4; i++) begin
            rd_en = 1;
            @(posedge clk);
            if (data_out !== i + 1) $error("Data mismatch");
        end
        rd_en = 0;

        // Test assertions
        $display("Testing overflow assertion...");
        for (int i = 0; i < 6; i++) begin
            wr_en = 1;
            data_in = i + 10;
            @(posedge clk);
        end

        $display("Testing underflow assertion...");
        for (int i = 0; i < 6; i++) begin
            rd_en = 1;
            @(posedge clk);
        end

        $display("Test completed");
        #100 $finish;
    end
endmodule

assertions:
// SystemVerilog Assertions
property no_write_when_full;
    @(posedge clk) disable iff (!rst_n)
    (wr_en && full) |-> (##1 data_out == $past(data_out));
endproperty

property no_read_when_empty;
    @(posedge clk) disable iff (!rst_n)
    (rd_en && empty) |-> (##1 data_out == $past(data_out));
endproperty

property data_integrity;
    @(posedge clk) disable iff (!rst_n)
    (wr_en && !full) |=> (##[1:4] (rd_en && !empty) && (data_out == $past(data_in, 1)));
endproperty

// Assert the properties
assert_fifo_full: assert property (no_write_when_full)
    else $error("FIFO overflow: Write attempted when full!");

assert_fifo_empty: assert property (no_read_when_empty)
    else $error("FIFO underflow: Read attempted when empty!");

assert_data_ok: assert property (data_integrity)
    else $error("Data integrity violation!");

