module alu(
    input logic [31:0] a, b,
    input logic [2:0] op,
    output logic [31:0] result,
    output logic zero, overflow
);
    // ALU implementation
    always_comb begin
        case(op)
            3'b000: result = a + b;          // ADD
            3'b001: result = a - b;          // SUB
            3'b010: result = a & b;          // AND
            3'b011: result = a | b;          // OR
            3'b100: result = a ^ b;          // XOR
            3'b101: result = ~a;             // NOT
            3'b110: result = a << 1;         // SHL
            3'b111: result = a >> 1;         // SHR
            default: result = 0;
        endcase

        zero = (result == 0);
        overflow = (op == 0) && (a[31] == b[31]) && (result[31] != a[31]);
    end
endmodule

